fn fixed(mut value:u128)->([i16;11],i16){let mut result=[0;11];if value==0{return(result,0);}let skew=i16::from(value%2==0);value+=skew as u128;let mut pos=0;while value!=0{let low=value%4096;let mut remaining=value/4096;let digit=if remaining!=0&&remaining%2==0{remaining+=1;low as i16-4096}else{low as i16};result[pos]=digit;value=remaining;pos+=1;}
 for j in 1..11{let middle=result[j];if middle==1&&result[j-1]<0{result[j-1]+=4096;result[j]=0;}else if middle== -1&&result[j-1]>0{result[j-1]-=4096;result[j]=0;}}(result,skew)}
fn check(value:u128,d:[i16;11],skew:i16){let result=d.into_iter().rev().fold(0i128,|a,d|a*4096+d as i128)-skew as i128;assert_eq!(result,value as i128);}
#[derive(Default,Clone,Copy)]struct Cost{aff:u64,proj:u64,active:u64,invoked:u64}
impl Cost{fn add(&mut self,b:Self){self.aff+=b.aff;self.proj+=b.proj;self.active+=b.active;self.invoked+=b.invoked;}fn verify(&self,v:&Value){assert_eq!(self.aff,n(v,"affine_tree_or_fill_pairs"));assert_eq!(self.proj,n(v,"projective_add_sub_calls"));assert_eq!(self.aff+self.proj,n(v,"all_point_add_calls"));assert_eq!(self.active,n(v,"active_doublings"));assert_eq!(self.invoked,n(v,"invoked_doublings"));}}
// Independent closed count of the correction trees: each segment contains
// the leading half of every block at one binary scale. No reducer imported.
fn weight(mask:&[bool])->Cost{let mut result=Cost::default();let mut occupied_groups=vec![];for group in mask.chunks(256){let mut active=group.iter().filter(|&&v|v).count()as u64;result.aff+=active.saturating_sub(1);let live=active!=0;occupied_groups.push(live);let mut span=2;while span<=group.len(){active=group.chunks(span).filter(|g|g[..span/2].iter().any(|&v|v)).count()as u64;result.aff+=active.saturating_sub(1);result.proj+=u64::from(active!=0&&live);result.invoked+=1;result.active+=u64::from(live);span*=2;}}
let(mut sum,mut offset,mut running)=(false,false,false);for active in occupied_groups.into_iter().rev(){result.proj+=u64::from(sum&&active)+u64::from(offset&&running)+u64::from(running&&active);sum|=active;offset|=running;running|=active;}result.invoked+=8;result.active+=8*u64::from(offset);result.proj+=u64::from(sum&&offset);result}
